func TestErrorVsFatal(t *testing.T) {
	res, err := setup()
	if err != nil {
		t.Fatalf("setup failed: %v", err) // stop: res is unusable
	}
	if res.value != 42 {
		t.Errorf("value=%d want 42", res.value) // record, keep going
	}
}

