package solution

import "strconv"

// FizzBuzz returns the FizzBuzz string for n.
func FizzBuzz(n int) string {
	switch {
	case n%15 == 0: // divisible by both 3 and 5
		return "FizzBuzz"
	case n%3 == 0:
		return "Fizz"
	case n%5 == 0:
		return "Buzz"
	default:
		return strconv.Itoa(n) // number as a string
	}
}

