func TestParse(t *testing.T) {
	cases := []struct{ name, in string; want int }{
		{"one", "1", 1}, {"two", "2", 2}, {"three", "3", 3},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			if got := Parse(c.in); got != c.want { // t.Errorf keeps going
				t.Errorf("Parse(%q)=%d want %d", c.in, got, c.want)
			}
		})
	}
}

func TestParseRange(t *testing.T) {
	cases := []struct {
		name       string
		in         string
		wantLo     int
		wantHi     int
		wantErr    bool
	}{
		{"valid", "3-7", 3, 7, false},
		{"reversed", "7-3", 0, 0, true},
		{"non-numeric", "a-b", 0, 0, true},
		{"empty", "", 0, 0, true},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			lo, hi, err := ParseRange(c.in)
			if (err != nil) != c.wantErr { // error presence must match
				t.Fatalf("ParseRange(%q) err=%v, wantErr=%v", c.in, err, c.wantErr)
			}
			if c.wantErr {
				return // on expected error, lo/hi are meaningless
			}
			if lo != c.wantLo || hi != c.wantHi {
				t.Errorf("ParseRange(%q) = (%d,%d), want (%d,%d)", c.in, lo, hi, c.wantLo, c.wantHi)
			}
		})
	}
}

func TestDivide(t *testing.T) {
	cases := []struct {
		name    string
		a, b    int
		want    int
		wantErr bool
	}{
		{"exact", 6, 3, 2, false},
		{"truncates", 7, 2, 3, false}, // integer division
		{"by zero", 1, 0, 0, true},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			got, err := Divide(c.a, c.b)
			if (err != nil) != c.wantErr { // error presence must match
				t.Fatalf("Divide(%d,%d) err=%v, wantErr=%v", c.a, c.b, err, c.wantErr)
			}
			if err == nil && got != c.want {
				t.Errorf("Divide(%d,%d)=%d, want %d", c.a, c.b, got, c.want)
			}
		})
	}
}
